import 'dart:ui' as ui;
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:hyzen_pharmd/core/widgets/profile_avatar.dart';
import 'package:hyzen_pharmd/features/auth/domain/student_profile.dart';

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  test('All selectable avatars decode and survive profile serialization', () async {
    expect(ProfileAvatar.choices.where((id) => id.startsWith('genz_')).length, 12);
    for (final id in [...ProfileAvatar.choices, ...ProfileAvatar.legacyChoices]) {
      final bytes = await rootBundle.load('assets/avatars/$id.webp');
      final codec = await ui.instantiateImageCodec(bytes.buffer.asUint8List());
      final frame = await codec.getNextFrame();
      expect(frame.image.width, greaterThan(0));
      if (id.startsWith('genz_')) {
        expect(frame.image.width, 320);
        expect(frame.image.height, 320);
      }
      frame.image.dispose();
      codec.dispose();
      final profile = StudentProfile.fromMap('test', {'photoUrl': 'avatar:$id'});
      final restored = StudentProfile.fromMap('test', profile.toWriteMap());
      final image = ProfileAvatar.imageFor(restored.photoUrl) as AssetImage;
      expect(image.assetName, 'assets/avatars/$id.webp');
    }
  });
  test('Legacy IDs and HTTPS photos remain usable; local paths fall back', () {
    expect(ProfileAvatar.imageFor('avatar:male_1'), isA<AssetImage>());
    expect(ProfileAvatar.imageFor('https://example.com/photo.jpg'), isA<NetworkImage>());
    for (final value in [null, '', 'avatar:unknown', '/private/photo.jpg', 'file:///photo.jpg']) {
      expect(ProfileAvatar.imageFor(value), isNull);
    }
  });
}

