class HyzenArt extends StatelessWidget {
  const HyzenArt(this.name, {super.key, this.size = 160, this.animate = true});
  final String name;
  final double size;
  final bool animate;
  @override
  Widget build(BuildContext context) {
    final image = Image.asset(
    'assets/illustrations/genz_${name == 'home' ? 'welcome' : name}.webp',
    width: size,
    height: size,
    fit: BoxFit.contain,
    cacheWidth: (size * 2).round(),
    excludeFromSemantics: true,
    errorBuilder: (context, error, stackTrace) => Image.asset(
      'assets/illustrations/$name.png', width: size, height: size,
      fit: BoxFit.contain, excludeFromSemantics: true,
    ),
    );
    return animate ? ArtEntrance(child: image) : image;
  }
}

class HyzenBanner extends StatelessWidget {
