import 'package:flutter/material.dart';

/// A short decorative entrance; never gates input or route readiness.
class ArtEntrance extends StatelessWidget {
  const ArtEntrance({super.key, required this.child});
  final Widget child;
  @override
  Widget build(BuildContext context) {
    if (MediaQuery.disableAnimationsOf(context)) return child;
    return TweenAnimationBuilder<double>(
      tween: Tween(begin: 0, end: 1),
      duration: const Duration(milliseconds: 450),
      curve: Curves.easeOutCubic,
      child: child,
      builder: (context, value, child) => Opacity(
        opacity: value,
        child: Transform.translate(offset: Offset(0, 14 * (1 - value)), child: child),
      ),
    );
  }
}

