lib/core/widgets/hyzen_symbol.dart:
import 'package:flutter/material.dart';

enum HyzenSymbolKind { home, study, pdf, shop, profile, campus, notes, special, quiz, papers, subject, folder, bookmark, scan, crop, rotate, reorder, enhance, exportFile, image, cart, order, notification, timer, ranking, duel, registration, download, offline, error, pause, check }

/// Original Hyzen dock glyphs on a common 24-unit, 1.8-unit stroke grid.
/// The containing destination supplies its accessible label and selected state.
class HyzenSymbol extends StatelessWidget {
  const HyzenSymbol(this.kind, {super.key, required this.color, this.size = 24});
  final HyzenSymbolKind kind;
  final Color color;
  final double size;
  @override
  Widget build(BuildContext context) => SizedBox.square(
    dimension: size,
    child: CustomPaint(painter: _SymbolPainter(kind, color)),
  );
}

class _SymbolPainter extends CustomPainter {
  const _SymbolPainter(this.kind, this.color);
  final HyzenSymbolKind kind;
  final Color color;
  @override
  void paint(Canvas canvas, Size size) {
    canvas.save();
    canvas.scale(size.width / 24, size.height / 24);
    final pen = Paint()..color = color..style = PaintingStyle.stroke
      ..strokeWidth = 1.8..strokeCap = StrokeCap.round..strokeJoin = StrokeJoin.round;
    void line(double x, double y, double endX, double endY) =>
      canvas.drawLine(Offset(x, y), Offset(endX, endY), pen);
    void poly(List<double> points) {
      final path = Path()..moveTo(points[0], points[1]);
      for (var i = 2; i < points.length; i += 2) { path.lineTo(points[i], points[i + 1]); }
      canvas.drawPath(path, pen);
    }
    void box(double x, double y, double width, double height) => canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(x, y, width, height), const Radius.circular(2)), pen);
    void circle(double x, double y, double radius) => canvas.drawCircle(Offset(x, y), radius, pen);
    switch (kind) {
      case HyzenSymbolKind.home:
        canvas.drawPath(Path()..moveTo(3, 10)..lineTo(12, 3)..lineTo(21, 10), pen);
        canvas.drawPath(Path()..moveTo(5, 9)..lineTo(5, 21)..lineTo(10, 21)
          ..lineTo(10, 15)..lineTo(14, 15)..lineTo(14, 21)..lineTo(19, 21)..lineTo(19, 9), pen);
        line(10, 10, 14, 10);
      case HyzenSymbolKind.study:
        canvas.drawPath(Path()..moveTo(12, 6)..quadraticBezierTo(7, 3, 3, 5)
          ..lineTo(3, 19)..quadraticBezierTo(7, 17, 12, 20)
          ..quadraticBezierTo(17, 17, 21, 19)..lineTo(21, 5)
          ..quadraticBezierTo(17, 3, 12, 6)..lineTo(12, 20), pen);
        line(6, 9, 9, 10); line(6, 13, 9, 14);
        line(15, 10, 18, 9); line(15, 14, 18, 13);
      case HyzenSymbolKind.pdf:
        canvas.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(7, 5, 10, 14), const Radius.circular(1.5)), pen);
        canvas.drawPath(Path()..moveTo(3, 8)..lineTo(3, 3)..lineTo(8, 3)
          ..moveTo(16, 3)..lineTo(21, 3)..lineTo(21, 8)
          ..moveTo(21, 16)..lineTo(21, 21)..lineTo(16, 21)
          ..moveTo(8, 21)..lineTo(3, 21)..lineTo(3, 16), pen);
        line(10, 9, 14, 9); line(10, 12, 14, 12); line(10, 15, 12, 15);
      case HyzenSymbolKind.shop:
        canvas.drawPath(Path()..moveTo(4, 9)..lineTo(6, 3)..lineTo(18, 3)
          ..lineTo(20, 9)..quadraticBezierTo(18, 13, 16, 9)
          ..quadraticBezierTo(14, 13, 12, 9)..quadraticBezierTo(10, 13, 8, 9)
          ..quadraticBezierTo(6, 13, 4, 9), pen);
        canvas.drawPath(Path()..moveTo(5, 12)..lineTo(5, 21)..lineTo(19, 21)..lineTo(19, 12), pen);
        canvas.drawPath(Path()..moveTo(10, 21)..lineTo(10, 15)..lineTo(14, 15)..lineTo(14, 21), pen);
      case HyzenSymbolKind.profile:
        circle(12, 7, 4); canvas.drawArc(const Rect.fromLTWH(4, 14, 16, 14), 3.14, 3.14, false, pen);
      case HyzenSymbolKind.campus:
        poly([2,8,12,3,22,8,12,13,2,8]); poly([6,11,6,17,12,20,18,17,18,11]); line(22,8,22,16);
      case HyzenSymbolKind.notes:
        box(5,3,14,18); line(9,3,9,21); line(12,8,16,8); line(12,12,16,12); line(12,16,15,16);
      case HyzenSymbolKind.special:
