      case HyzenSymbolKind.papers:
        box(3,6,15,15); poly([7,6,7,3,21,3,21,17]); line(7,11,14,11); line(7,15,14,15); line(7,18,11,18);
      case HyzenSymbolKind.subject:
        poly([9,3,15,3,14,3,14,10,20,19,19,21,5,21,4,19,10,10,10,3]); line(7,16,17,16); circle(12,13,1);
      case HyzenSymbolKind.folder:
        poly([3,20,3,5,10,5,12,8,21,8,21,20,3,20]); line(7,12,17,12);
      case HyzenSymbolKind.bookmark:
        poly([6,3,18,3,18,21,12,17,6,21,6,3]); line(9,7,15,7);
      case HyzenSymbolKind.scan:
        poly([3,8,3,3,8,3]); poly([16,3,21,3,21,8]); poly([21,16,21,21,16,21]); poly([8,21,3,21,3,16]);
        box(7,6,10,12); line(5,12,19,12);
      case HyzenSymbolKind.crop:
        poly([3,6,18,6,18,21]); poly([6,3,6,18,21,18]); poly([10,14,14,14,14,10]);
      case HyzenSymbolKind.rotate:
        canvas.drawArc(const Rect.fromLTWH(4,5,16,16), -.8, 4.8, false, pen); poly([14,3,20,5,18,11]); line(10,11,14,11);
      case HyzenSymbolKind.reorder:
        poly([4,6,7,3,10,6]); line(7,3,7,21); poly([14,18,17,21,20,18]); line(17,3,17,21); line(11,9,13,9); line(11,15,13,15);
      case HyzenSymbolKind.enhance:
        poly([12,3,14,10,21,12,14,14,12,21,10,14,3,12,10,10,12,3]); line(18,3,18,6); line(17,4.5,19,4.5);
      case HyzenSymbolKind.exportFile:
        poly([10,3,4,3,4,21,18,21,18,15]); poly([12,4,21,4,21,13]); line(11,14,21,4);
      case HyzenSymbolKind.image:
        box(3,3,18,18); circle(8,8,2); poly([4,18,10,12,14,16,17,13,21,18]);
      case HyzenSymbolKind.cart:
        poly([2,3,5,3,8,16,19,16,22,6,6,6]); circle(9,21,1); circle(18,21,1); line(10,10,18,10);
      case HyzenSymbolKind.order:
        poly([3,7,12,3,21,7,21,18,12,22,3,18,3,7,12,11,21,7]); line(12,11,12,22); poly([7,5,16,9,16,13]);
      case HyzenSymbolKind.notification:
        canvas.drawPath(Path()..moveTo(5,17)..lineTo(7,14)..lineTo(7,8)..quadraticBezierTo(12,0,17,8)..lineTo(17,14)..lineTo(19,17)..close(),pen);
        canvas.drawArc(const Rect.fromLTWH(9,17,6,5),0,3.14,false,pen);
      case HyzenSymbolKind.timer:
        circle(12,14,8); line(9,2,15,2); line(12,2,12,6); poly([12,9,12,14,16,16]); line(18,5,20,7);
      case HyzenSymbolKind.ranking:
        poly([3,21,3,13,9,13,9,7,15,7,15,16,21,16,21,21,3,21]); circle(12,3,1);
      case HyzenSymbolKind.duel:
        poly([3,5,8,5,8,10]); poly([21,19,16,19,16,14]); line(3,19,19,3); line(10,12,3,5); line(14,12,21,19);
      case HyzenSymbolKind.registration:
        box(4,4,16,17); box(9,2,6,4); poly([8,14,11,17,17,10]);
      case HyzenSymbolKind.download:
        poly([3,16,3,21,21,21,21,16]); poly([7,10,12,15,17,10]); line(12,3,12,15);
      case HyzenSymbolKind.offline:
        box(3,4,18,16); poly([7,14,10,17,17,9]); line(8,8,12,8);
      case HyzenSymbolKind.error:
        circle(12,12,9); line(12,7,12,13); circle(12,17,.5);
      case HyzenSymbolKind.pause:
        box(5,4,4,16); box(15,4,4,16);
      case HyzenSymbolKind.check:
        circle(12,12,9); poly([7,12,11,16,18,8]);

    }
    canvas.restore();
  }
  @override
  bool shouldRepaint(_SymbolPainter oldDelegate) => kind != oldDelegate.kind || color != oldDelegate.color;
}

