import 'dart:math' as math;
import 'dart:typed_data';
import 'dart:ui' as ui;
import 'package:flutter/material.dart';

/// Same source rectangle is used for preview and export. Coordinates remain
/// inside the decoded image even for portrait, landscape and zoomed crops.
Rect profileCropRect(int width, int height, double zoom, double x, double y) {
  final side = math.min(width, height) / zoom.clamp(1.0, 3.0);
  return Rect.fromLTWH(
    (width - side) * ((x.clamp(-1.0, 1.0) + 1) / 2),
    (height - side) * ((y.clamp(-1.0, 1.0) + 1) / 2), side, side,
  );
}

Future<Uint8List> renderProfileCrop(ui.Image image, Rect source) async {
  final recorder = ui.PictureRecorder();
  Canvas(recorder).drawImageRect(image, source,
    const Rect.fromLTWH(0, 0, 512, 512), Paint()..filterQuality = FilterQuality.high);
  final picture = recorder.endRecording();
  ui.Image? output;
  try {
    output = await picture.toImage(512, 512);
    final data = await output.toByteData(format: ui.ImageByteFormat.png);
    if (data == null) throw StateError('Photo could not be prepared.');
    return data.buffer.asUint8List();
  } finally { output?.dispose(); picture.dispose(); }
}

Future<Uint8List?> cropProfilePhoto(BuildContext context, Uint8List bytes) async {
  if (bytes.length > 20 * 1024 * 1024) {
    throw const FormatException('Choose a photo smaller than 20 MB.');
  }
  final buffer = await ui.ImmutableBuffer.fromUint8List(bytes);
  ui.ImageDescriptor? descriptor;
  ui.Codec? codec;
  ui.Image? image;
  bool ownedBySheet = false;
  try {
    descriptor = await ui.ImageDescriptor.encoded(buffer);
    final scale = math.min(1.0, 1600 / math.max(descriptor.width, descriptor.height));
    codec = await descriptor.instantiateCodec(
      targetWidth: math.max(1, (descriptor.width * scale).round()),
      targetHeight: math.max(1, (descriptor.height * scale).round()),
    );
    image = (await codec.getNextFrame()).image;
    if (!context.mounted) return null;
    return await showModalBottomSheet<Uint8List>(
      context: context, isScrollControlled: true, useSafeArea: true,
      builder: (_) {
        ownedBySheet = true;
        return PhotoCropSheet(image: image!, disposeImage: true);
      },
    );
  } finally {
    if (!ownedBySheet) image?.dispose();
    codec?.dispose();
    descriptor?.dispose();
    buffer.dispose();
  }
}

class PhotoCropSheet extends StatefulWidget {
  const PhotoCropSheet({super.key, required this.image, this.disposeImage = false});
  final ui.Image image;
  final bool disposeImage;
  @override
  State<PhotoCropSheet> createState() => _PhotoCropSheetState();
}

class _PhotoCropSheetState extends State<PhotoCropSheet> {
  double _zoom = 1, _x = 0, _y = 0;
  bool _busy = false;
  String? _error;
  @override
  void dispose() {
    if (widget.disposeImage) widget.image.dispose();
    super.dispose();
  }
  Rect get _rect => profileCropRect(widget.image.width, widget.image.height, _zoom, _x, _y);

  Future<void> _usePhoto() async {
    if (_busy) return;
    setState(() { _busy = true; _error = null; });
    try {
      final bytes = await renderProfileCrop(widget.image, _rect);
      if (mounted) Navigator.pop(context, bytes);
    } catch (_) {
      if (mounted) setState(() { _busy = false; _error = 'Could not prepare photo. Please retry.'; });
    }
  }

  @override
  Widget build(BuildContext context) => PopScope(
    canPop: !_busy,
    child: SizedBox(
      height: MediaQuery.sizeOf(context).height * .9,
      child: ListView(padding: const EdgeInsets.all(20), children: [
        Text('Crop and preview', style: Theme.of(context).textTheme.headlineSmall),
        const SizedBox(height: 8),
        const Text('Adjust your photo. It uploads only after you choose Use photo.'),
        const SizedBox(height: 16),
        Center(child: ConstrainedBox(constraints: const BoxConstraints(maxWidth: 300),
          child: AspectRatio(aspectRatio: 1, child: Semantics(
            label: 'Profile photo crop preview', image: true,
            child: CustomPaint(painter: _CropPainter(widget.image, _rect)),
          )),
        )),
        for (final control in [
          ('Zoom', _zoom, 1.0, 3.0, (double v) => setState(() => _zoom = v)),
          ('Horizontal position', _x, -1.0, 1.0, (double v) => setState(() => _x = v)),
          ('Vertical position', _y, -1.0, 1.0, (double v) => setState(() => _y = v)),
        ]) ...[
          Text(control.$1),
          Slider(label: control.$1, value: control.$2, min: control.$3, max: control.$4,
            onChanged: _busy ? null : control.$5,
            semanticFormatterCallback: (v) => '${control.$1}: ${v.toStringAsFixed(1)}'),
        ],
        if (_error != null) Text(_error!, semanticsLabel: _error),
        Wrap(spacing: 12, runSpacing: 8, alignment: WrapAlignment.end, children: [
          TextButton(onPressed: _busy ? null : () => Navigator.pop(context), child: const Text('Cancel')),
          FilledButton(onPressed: _busy ? null : _usePhoto,
            child: Text(_busy ? 'Preparing…' : 'Use photo')),
        ]),
      ]),
    ),
  );
}

class _CropPainter extends CustomPainter {
  const _CropPainter(this.image, this.source);
  final ui.Image image;
  final Rect source;
  @override
  void paint(Canvas canvas, Size size) {
    canvas.drawImageRect(image, source, Offset.zero & size,
      Paint()..filterQuality = FilterQuality.medium);
  }
  @override
  bool shouldRepaint(_CropPainter oldDelegate) => image != oldDelegate.image || source != oldDelegate.source;
}

