import 'dart:async';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../app/providers.dart';
import '../../../core/widgets/hyzen_art.dart';

class WelcomePlayback {
  WelcomePlayback(this.uid);
  final String? uid;
  bool _played = false;
  bool claim() {
    if (uid == null || _played) return false;
    _played = true;
    return true;
  }
}

/// Replaced at sign-out/account change; never persisted as private identity data.
final welcomePlaybackProvider = Provider<WelcomePlayback>((ref) {
  final uid = ref.watch(authStateProvider.select((state) => state.valueOrNull?.uid));
  return WelcomePlayback(uid);
});

class SessionWelcomeArt extends ConsumerStatefulWidget {
  const SessionWelcomeArt({super.key, required this.size, required this.profileReady});
  final double size;
  final bool profileReady;
  @override
  ConsumerState<SessionWelcomeArt> createState() => _SessionWelcomeArtState();
}

class _SessionWelcomeArtState extends ConsumerState<SessionWelcomeArt> {
  WelcomePlayback? _session;
  bool _animate = false;
  Timer? _timer;
  @override
  void dispose() { _timer?.cancel(); super.dispose(); }
  @override
  Widget build(BuildContext context) {
    final session = ref.watch(welcomePlaybackProvider);
    if (widget.profileReady && !identical(_session, session)) {
      _session = session;
      _timer?.cancel();
      _animate = session.claim() && !MediaQuery.disableAnimationsOf(context);
      if (_animate) {
        _timer = Timer(const Duration(milliseconds: 450), () {
          if (mounted) setState(() => _animate = false);
        });
      }
    }
    final animate = _animate && !MediaQuery.disableAnimationsOf(context);
    return Column(mainAxisSize: MainAxisSize.min, children: [
      HyzenArt('home', size: widget.size, animate: animate),
      if (animate)
        TextButton(onPressed: () {
          _timer?.cancel(); setState(() => _animate = false);
        }, child: const Text('Skip animation')),
    ]);
  }
}

