import 'dart:ui' as ui;
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:hyzen_pharmd/core/widgets/photo_crop_sheet.dart';
import 'package:hyzen_pharmd/core/widgets/profile_avatar.dart';
import 'package:hyzen_pharmd/features/auth/domain/student_profile.dart';

void main() {
  test('Portrait and landscape crops stay bounded at every control extreme', () {
    for (final size in [const Size(2400, 1200), const Size(800, 2400)]) {
      for (final zoom in [1.0, 2.0, 3.0]) {
        for (final x in [-1.0, 0.0, 1.0]) {
          for (final y in [-1.0, 0.0, 1.0]) {
            final rect = profileCropRect(size.width.toInt(), size.height.toInt(), zoom, x, y);
            expect(rect.width, closeTo(rect.height, 1e-7));
            expect(rect.left, greaterThanOrEqualTo(0));
            expect(rect.top, greaterThanOrEqualTo(0));
            expect(rect.right, lessThanOrEqualTo(size.width + 1e-7));
            expect(rect.bottom, lessThanOrEqualTo(size.height + 1e-7));
          }
        }
      }
    }
    expect(profileCropRect(1200, 800, 1, 1, 0), const Rect.fromLTWH(400, 0, 800, 800));
  });
  test('Explicit removal survives serialization and renders the initial fallback', () {
    final original = StudentProfile.fromMap('user', {'photoUrl': 'avatar:genz_01'});
    final removed = original.copyWith(photoUrl: '');
    final restored = StudentProfile.fromMap('user', removed.toWriteMap());
    expect(restored.photoUrl, '');
    expect(ProfileAvatar.imageFor(restored.photoUrl), isNull);
    expect(original.photoUrl, 'avatar:genz_01');
  });
  test('Crop export contains the selected region as a square PNG', () async {
    final recorder = ui.PictureRecorder();
    final canvas = Canvas(recorder);
    canvas.drawRect(const Rect.fromLTWH(0, 0, 10, 10), Paint()..color = const Color(0xFFFF0000));
    canvas.drawRect(const Rect.fromLTWH(10, 0, 10, 10), Paint()..color = const Color(0xFF0000FF));
    final picture = recorder.endRecording();
    final image = await picture.toImage(20, 10);
    try {
      final bytes = await renderProfileCrop(image, profileCropRect(20, 10, 1, 1, 0));
      final codec = await ui.instantiateImageCodec(bytes);
      final result = (await codec.getNextFrame()).image;
      try {
        expect(result.width, 512); expect(result.height, 512);
        final rgba = await result.toByteData(format: ui.ImageByteFormat.rawRgba);
        final center = (256 * 512 + 256) * 4;
        expect(rgba!.buffer.asUint8List().sublist(center, center + 4), [0, 0, 255, 255]);
      } finally { result.dispose(); codec.dispose(); }
    } finally { image.dispose(); picture.dispose(); }
  });
  testWidgets('Crop cancellation dismisses without selecting or exporting a photo', (tester) async {
    final image = await tester.runAsync(() async {
      final recorder = ui.PictureRecorder();
      Canvas(recorder).drawColor(Colors.teal, BlendMode.src);
      final picture = recorder.endRecording();
      try { return await picture.toImage(20, 20); } finally { picture.dispose(); }
    });
    addTearDown(() => image!.dispose());
    Object? selected = 'unchanged';
    await tester.pumpWidget(MaterialApp(home: Builder(builder: (context) => TextButton(
      onPressed: () async {
        selected = await showModalBottomSheet<Object>(context: context,
          isScrollControlled: true, builder: (_) => PhotoCropSheet(image: image!));
      }, child: const Text('Open crop'),
    ))));
    await tester.tap(find.text('Open crop')); await tester.pumpAndSettle();
    expect(find.text('Crop and preview'), findsOneWidget);
    await tester.scrollUntilVisible(find.text('Cancel'), 180,
      scrollable: find.descendant(of: find.byType(PhotoCropSheet), matching: find.byType(Scrollable)));
    await tester.tap(find.text('Cancel')); await tester.pumpAndSettle();
    expect(selected, isNull);
    expect(find.text('Crop and preview'), findsNothing);
    expect(tester.takeException(), isNull);
  });
}

