import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:hyzen_pharmd/features/home/presentation/session_welcome_art.dart';

void main() {
  test('Welcome is claimed once per authenticated session, never for signed-out state', () {
    expect(WelcomePlayback(null).claim(), isFalse);
    final session = WelcomePlayback('student-a');
    expect(session.claim(), isTrue);
    expect(session.claim(), isFalse);
    expect(WelcomePlayback('student-a').claim(), isTrue);
    expect(WelcomePlayback('student-b').claim(), isTrue);
  });
  testWidgets('Profile readiness, skip and remount preserve once-per-session behavior', (tester) async {
    final session = WelcomePlayback('student-a');
    final container = ProviderContainer(overrides: [welcomePlaybackProvider.overrideWithValue(session)]);
    addTearDown(container.dispose);
    Widget app({required bool ready, bool show = true}) => UncontrolledProviderScope(
      container: container, child: MaterialApp(home: show ? SessionWelcomeArt(size: 120, profileReady: ready) : const SizedBox()),
    );
    await tester.pumpWidget(app(ready: false));
    expect(find.text('Skip animation'), findsNothing);
    await tester.pumpWidget(app(ready: true));
    expect(find.text('Skip animation'), findsOneWidget);
    await tester.tap(find.text('Skip animation')); await tester.pump();
    expect(find.text('Skip animation'), findsNothing);
    await tester.pumpWidget(app(ready: true, show: false));
    await tester.pumpWidget(app(ready: true));
    expect(find.text('Skip animation'), findsNothing);
    await tester.pumpAndSettle();
    expect(tester.takeException(), isNull);
  });
}

