import 'package:flutter/material.dart';
import '../../../core/widgets/hyzen_symbol.dart';
import '../domain/download_record.dart';

/// Display only measured bytes; legacy progress values cannot invent a percent.
double? measuredDownloadProgress(DownloadRecord record) =>
    record.totalBytes != null && record.totalBytes! > 0
      ? (record.sizeBytes / record.totalBytes!).clamp(0.0, 1.0).toDouble() : null;

String downloadStatusLabel(DownloadRecord record) {
  if (record.isReady) return 'Downloaded · Offline';
  if (record.status == DownloadStatus.paused) return 'Paused · tap to resume';
  if (record.status == DownloadStatus.downloading) {
    final value = measuredDownloadProgress(record);
    return value == null ? 'Downloading · ${formatBytes(record.sizeBytes)}'
      : 'Downloading ${(value * 100).round()}%';
  }
  return 'Interrupted · tap to retry';
}

class TransferStatus extends StatelessWidget {
  const TransferStatus({super.key, required this.record});
  final DownloadRecord record;
  @override
  Widget build(BuildContext context) {
    final reduced = MediaQuery.disableAnimationsOf(context);
    final progress = measuredDownloadProgress(record);
    final label = downloadStatusLabel(record);
    final kind = record.isReady ? HyzenSymbolKind.check
      : switch (record.status) {
        DownloadStatus.downloading => HyzenSymbolKind.download,
        DownloadStatus.paused => HyzenSymbolKind.pause,
        _ => HyzenSymbolKind.error,
      };
    final color = record.isReady ? Theme.of(context).colorScheme.primary
      : record.status == DownloadStatus.failed ? Theme.of(context).colorScheme.error
      : Theme.of(context).colorScheme.onSurfaceVariant;
    return Semantics(label: label, child: ExcludeSemantics(child: Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        if (record.status == DownloadStatus.downloading) ...[
          if (progress != null && !reduced)
            TweenAnimationBuilder<double>(
              tween: Tween(begin: progress, end: progress),
              duration: const Duration(milliseconds: 140),
              builder: (_, value, __) => LinearProgressIndicator(value: value, minHeight: 5),
            )
          else LinearProgressIndicator(value: reduced ? progress ?? 0 : progress, minHeight: 5),
          const SizedBox(height: 6),
        ],
        AnimatedSwitcher(
          duration: reduced ? Duration.zero : const Duration(milliseconds: 160),
          child: Row(key: ValueKey('${record.status.name}:${record.isReady}'), children: [
            HyzenSymbol(kind, color: color, size: 16),
            const SizedBox(width: 6),
            Expanded(child: Text(label, style: Theme.of(context).textTheme.labelSmall?.copyWith(color: color))),
          ]),
        ),
      ],
    )));
  }
}

